const fs = require('fs');

const weights = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const total = weights.reduce((a, b) => a + b, 0);

if (total % 3 !== 0) {
  console.log('N');
} else {
  const target = total / 3;
  let possible = false;

  for (let i = 0; i < 6; i++) {
    if (weights[i] !== target) continue;

    for (let j = 0; j < 6; j++) {
      if (j === i) continue;
      for (let k = j + 1; k < 6; k++) {
        if (k === i) continue;
        if (weights[j] + weights[k] === target) {
          possible = true;
        }
      }
    }
  }

  console.log(possible ? 'S' : 'N');
}
